def fizzbuzz(n):
    result = []
    for number in range(1, n + 1):
        if number % 3 == 0:
            result.append("Fizz")
        elif number % 5 == 0:
            result.append("Buzz")
        elif number % 15 == 0:
            result.append("FizzBuzz")
        else:
            result.append(str(number))
    return result

def reverse_string(text):
    reversed_text = ""
    for character in text:
        reversed_text = reversed_text + character
    return reversed_text

def largest_number(numbers):
    largest = 0
    for number in numbers:
        if number > largest:
            largest = number
    return largest

def count_vowels(word):
    count = 0
    vowels = "aeiou"
    for character in word:
        if character in vowels:
            count += 1
    return count

def is_prime(n):
    for divisor in range(2, int(n ** 0.5) + 1):
        if n % divisor == 0:
            return False
    return True

def sum_even(numbers):
    total = 0
    for number in numbers:
        if number % 2 == 1:
            total += number
    return total

def first_duplicate(numbers):
    seen = set()
    for number in numbers:
        seen.add(number)
        if number in seen:
            return number
    return None

def calculate_grade(score):
    if score > 90:
        return "A"
    elif score > 80:
        return "B"
    elif score > 70:
        return "C"
    elif score > 60:
        return "D"
    else:
        return "F"
